-- G2.4 trusted Silver entity contracts. Shared columns provide the minimum lineage contract.
USE ROLE SYSADMIN;
USE DATABASE TRUSTED_AI_GOVERNANCE;
USE SCHEMA SILVER;

CREATE TABLE IF NOT EXISTS CUSTOMER (CUSTOMER_ID VARCHAR, CUSTOMER_TYPE VARCHAR, CUSTOMER_SEGMENT VARCHAR, RISK_TIER VARCHAR, CUSTOMER_STATUS VARCHAR, CREATED_DATE DATE, CUSTOMER_NAME VARCHAR, CITY VARCHAR, STATE VARCHAR, COUNTRY VARCHAR, CUSTOMER_NAME_MASKED VARCHAR, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS ACCOUNT (ACCOUNT_ID VARCHAR, CUSTOMER_ID VARCHAR, ACCOUNT_TYPE VARCHAR, ACCOUNT_STATUS VARCHAR, CURRENCY_CODE VARCHAR, OPEN_DATE DATE, ACCOUNT_COUNTRY VARCHAR, RELATIONSHIP_TIER VARCHAR, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS PAYMENT (PAYMENT_ID VARCHAR, ACCOUNT_ID VARCHAR, CUSTOMER_ID VARCHAR, PAYMENT_TIMESTAMP TIMESTAMP_NTZ, PAYMENT_DATE DATE, PAYMENT_TYPE VARCHAR, PAYMENT_CHANNEL VARCHAR, CURRENCY_CODE VARCHAR, PAYMENT_AMOUNT NUMBER(18,2), BENEFICIARY_COUNTRY VARCHAR, BENEFICIARY_TYPE VARCHAR, PAYMENT_STATUS VARCHAR, PROCESSING_SYSTEM VARCHAR, REQUESTED_EXECUTION_DATE DATE, ACTUAL_EXECUTION_DATE DATE, SOURCE_REFERENCE VARCHAR, DUPLICATE_DISPOSITION VARCHAR, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS PAYMENT_EXCEPTION (EXCEPTION_ID VARCHAR, PAYMENT_ID VARCHAR, CUSTOMER_ID VARCHAR, ACCOUNT_ID VARCHAR, EXCEPTION_TIMESTAMP TIMESTAMP_NTZ, EXCEPTION_DATE DATE, EXCEPTION_TYPE VARCHAR, EXCEPTION_REASON_CODE VARCHAR, EXCEPTION_CATEGORY VARCHAR, EXCEPTION_REASON_DESCRIPTION VARCHAR, SEVERITY VARCHAR, EXCEPTION_STATUS VARCHAR, ASSIGNED_TEAM VARCHAR, ASSIGNED_ANALYST_ID VARCHAR, RESOLUTION_STATUS VARCHAR, RESOLUTION_CODE VARCHAR, RESOLVED_TIMESTAMP TIMESTAMP_NTZ, SLA_DUE_TIMESTAMP TIMESTAMP_NTZ, DERIVED_HIGH_VALUE_FLAG BOOLEAN, REQUIRES_MANUAL_REVIEW BOOLEAN, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS SLA_EVENT (SLA_EVENT_ID VARCHAR, EXCEPTION_ID VARCHAR, SLA_TYPE VARCHAR, SLA_START_TIMESTAMP TIMESTAMP_NTZ, SLA_DUE_TIMESTAMP TIMESTAMP_NTZ, DERIVED_SLA_BREACHED_FLAG BOOLEAN, DERIVED_BREACH_MINUTES NUMBER, DERIVED_ESCALATION_REQUIRED BOOLEAN, DERIVED_SLA_STATUS VARCHAR, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS OPERATIONS_TEAM (TEAM_ID VARCHAR, TEAM_NAME VARCHAR, REGION VARCHAR, MANAGER_ID VARCHAR, TEAM_STATUS VARCHAR, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS OPERATIONS_USER (OPERATIONS_USER_ID VARCHAR, TEAM_ID VARCHAR, DISPLAY_NAME VARCHAR, BUSINESS_PERSONA VARCHAR, REGION VARCHAR, EMPLOYMENT_STATUS VARCHAR, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS REFERENCE_EXCEPTION_REASON (EXCEPTION_REASON_CODE VARCHAR, EXCEPTION_CATEGORY VARCHAR, BUSINESS_DEFINITION VARCHAR, DEFAULT_SEVERITY VARCHAR, MANUAL_REVIEW_DEFAULT BOOLEAN, ACTIVE_FLAG BOOLEAN, EFFECTIVE_DATE DATE, EXPIRY_DATE DATE, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS REFERENCE_PAYMENT_THRESHOLD (THRESHOLD_ID VARCHAR, CURRENCY_CODE VARCHAR, HIGH_VALUE_THRESHOLD NUMBER(18,2), EFFECTIVE_DATE DATE, EXPIRY_DATE DATE, APPROVAL_STATUS VARCHAR, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS GOVERNANCE_REFERENCE (GOVERNANCE_REFERENCE_ID VARCHAR, ASSET_TYPE VARCHAR, ASSET_IDENTIFIER VARCHAR, CLASSIFICATION VARCHAR, SENSITIVITY_LEVEL VARCHAR, PERMITTED_PURPOSE VARCHAR, OWNER VARCHAR, EFFECTIVE_DATE DATE, EXPIRY_DATE DATE, GOVERNANCE_STATUS VARCHAR, SOURCE_ID VARCHAR, BRONZE_RECORD_REFERENCE VARCHAR, SOURCE_FILE_NAME VARCHAR, SOURCE_FILE_ROW_NUMBER NUMBER, INGESTION_RUN_ID VARCHAR, TRANSFORMATION_RUN_ID VARCHAR, TRACE_ID VARCHAR, TRANSFORMED_AT TIMESTAMP_LTZ, SYNTHETIC_FLAG BOOLEAN, DQ_ADMISSION_STATUS VARCHAR);

USE ROLE SECURITYADMIN;
GRANT SELECT,INSERT,UPDATE,DELETE,TRUNCATE ON ALL TABLES IN SCHEMA TRUSTED_AI_GOVERNANCE.SILVER TO ROLE TRUSTED_AI_DATA_ENGINEER;
